/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: detail, mount
 *   Constants: sample, tone, session, track
 * Tests
 *   - tints the Playlist hero with the artwork tone and leaves the main pane untinted beneath it
 *   - uses the neutral hero tone without sampling when the Playlist has no managed artwork
 * @end-catalog */

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, cleanup, render, screen, waitFor } from '@testing-library/react';
import { MemoryRouter, Route, Routes } from 'react-router';

import { browserSessionQueryKey } from '../../api/session';
import { listenerCapabilitiesQueryKey } from '../../api/listenerCapabilities';
import { sampleArtworkTone } from '../../artwork/artworkTone';
import { neutralArtworkTone } from '../../artwork/useArtworkTone';
import { PlaylistDetailPage } from './PlaylistDetailPage';

vi.mock('../../artwork/artworkTone', () => ({ sampleArtworkTone: vi.fn() }));

const sample = vi.mocked(sampleArtworkTone);
const tone = { hero: '#2f7a5f', pane: '#1f5440' };
const session = {
  user: {
    id: 'viewer-1',
    email: 'listener@example.com',
    role: 'user',
    displayName: 'Listener',
    avatarRevision: 0,
    avatar: null,
    emailVerified: true
  }
};
const track = {
  contentType: 'audioTrack',
  id: 'track-1',
  title: 'Night',
  artworkUrl: '',
  artistNames: ['Finite Ensemble'],
  albumId: null,
  albumTitle: null,
  duration: '3:00',
  mediaType: 'audio',
  streamUrl: '/content/mediaTrack/stream/track-1'
};
const detail = (artworkUrl: string) => ({
  id: 'playlist-1',
  name: 'Quiet sequence',
  itemCount: 1,
  artworkUrl,
  revision: 1,
  createdAt: '2026-08-04T12:00:00.000Z',
  updatedAt: '2026-08-04T12:05:00.000Z',
  items: [{ itemId: 'item-1', audioTrackId: track.id, addedAt: '2026-08-04T12:01:00.000Z', availability: 'ready', audioTrack: track }]
});

const mount = (artworkUrl: string) => {
  vi.stubGlobal('fetch', vi.fn(async () => new Response(JSON.stringify(detail(artworkUrl)), {
    headers: { 'Content-Type': 'application/json', 'X-Finitude-Account-Viewer': 'viewer-1' }
  })));
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(browserSessionQueryKey, session);
  client.setQueryData(listenerCapabilitiesQueryKey, { playlists: true });
  const main = document.createElement('main');
  main.id = 'main-content';
  document.body.append(main);
  const view = render(
    <QueryClientProvider client={client}>
      <MemoryRouter initialEntries={['/playlists/playlist-1']}>
        <Routes><Route element={<PlaylistDetailPage />} path="/playlists/:playlistId" /></Routes>
      </MemoryRouter>
    </QueryClientProvider>,
    { container: main }
  );
  return { main, ...view };
};

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
  document.body.innerHTML = '';
});

test('tints the Playlist hero with the artwork tone and leaves the main pane untinted beneath it', async () => {
  let finish!: (value: typeof tone) => void;
  sample.mockReturnValue(new Promise((resolve) => { finish = resolve; }));
  const artwork = '/content/images/0000000000000000000000b7';
  const { main, unmount } = mount(artwork);
  const hero = (await screen.findByRole('heading', { level: 1, name: 'Quiet sequence' })).closest('header')!;
  const bar = (await screen.findByText('Quiet sequence', { selector: 'span' })).parentElement!;

  expect(hero.style.getPropertyValue('--tone-color')).toBe(neutralArtworkTone.hero);
  expect(bar.style.getPropertyValue('--tone-color')).toBe(neutralArtworkTone.pane);
  await waitFor(() => expect(sample).toHaveBeenCalledWith(`${artwork}/v1/96.webp`));

  await act(async () => finish(tone));
  expect(hero.style.getPropertyValue('--tone-color')).toBe(tone.hero);
  expect(bar.style.getPropertyValue('--tone-color')).toBe(tone.pane);
  expect(main.style.getPropertyValue('--tone-color')).toBe('');
  unmount();
  expect(main.style.getPropertyValue('--tone-color')).toBe('');
});

test('uses the neutral hero tone without sampling when the Playlist has no managed artwork', async () => {
  const { main } = mount('');
  const hero = (await screen.findByRole('heading', { level: 1, name: 'Quiet sequence' })).closest('header')!;
  expect(hero.style.getPropertyValue('--tone-color')).toBe(neutralArtworkTone.hero);
  expect(main.style.getPropertyValue('--tone-color')).toBe('');
  expect(sample).not.toHaveBeenCalled();
});
